package com.functionhall.controller;
import com.functionhall.dao.*;import com.functionhall.model.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.sql.Date;
@WebServlet("/book") public class BookingServlet extends HttpServlet{protected void doPost(HttpServletRequest q,HttpServletResponse p)throws IOException{User u=(User)q.getSession().getAttribute("user");if(u==null){p.sendRedirect("login.jsp");return;}try{int id=Integer.parseInt(q.getParameter("hallId"));FunctionHall h=new HallDAO().findById(id);Booking b=new Booking();b.setUserId(u.getUserId());b.setHallId(id);b.setBookingDate(Date.valueOf(q.getParameter("bookingDate")));b.setNumberOfGuests(Integer.parseInt(q.getParameter("guests")));b.setTotalAmount(h.getPricePerDay());int bid=new BookingDAO().create(b);if(bid>0)p.sendRedirect("payment.jsp?bookingId="+bid+"&amount="+h.getPricePerDay());else p.sendRedirect("booking.jsp?hallId="+id+"&error=1");}catch(Exception e){throw new IOException(e);}}}
